class Solution {
public:
    int minimumOperations(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> col_counts(n, vector<int>(10, 0));
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                col_counts[c][grid[r][c]]++;
            }
        }

        vector<int> dp(10);
        for (int d = 0; d < 10; ++d) {
            dp[d] = m - col_counts[0][d];
        }

        for (int c = 1; c < n; ++c) {
            vector<int> nxt_dp(10, 1e9);
            for (int d = 0; d < 10; ++d) {
                int cost = m - col_counts[c][d];
                for (int prev_d = 0; prev_d < 10; ++prev_d) {
                    if (prev_d != d) {
                        nxt_dp[d] = min(nxt_dp[d], dp[prev_d] + cost);
                    }
                }
            }
            dp = nxt_dp;
        }

        return *min_element(dp.begin(), dp.end());
    }
};

class Solution {
    public int minimumOperations(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] colCounts = new int[n][10];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                colCounts[c][grid[r][c]]++;
            }
        }

        int[] dp = new int[10];
        for (int d = 0; d < 10; d++) {
            dp[d] = m - colCounts[0][d];
        }

        for (int c = 1; c < n; c++) {
            int[] nxtDp = new int[10];
            Arrays.fill(nxtDp, Integer.MAX_VALUE);
            for (int d = 0; d < 10; d++) {
                int cost = m - colCounts[c][d];
                for (int prevD = 0; prevD < 10; prevD++) {
                    if (prevD != d) {
                        nxtDp[d] = Math.min(nxtDp[d], dp[prevD] + cost);
                    }
                }
            }
            dp = nxtDp;
        }

        int ans = Integer.MAX_VALUE;
        for (int v : dp) ans = Math.min(ans, v);
        return ans;
    }
}

var minimumOperations = function(grid) {
    const m = grid.length, n = grid[0].length;
    const colCounts = Array.from({length: n}, () => new Array(10).fill(0));
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            colCounts[c][grid[r][c]]++;
        }
    }

    let dp = new Array(10);
    for (let d = 0; d < 10; d++) {
        dp[d] = m - colCounts[0][d];
    }

    for (let c = 1; c < n; c++) {
        const nxtDp = new Array(10).fill(Infinity);
        for (let d = 0; d < 10; d++) {
            const cost = m - colCounts[c][d];
            for (let prevD = 0; prevD < 10; prevD++) {
                if (prevD !== d) {
                    nxtDp[d] = Math.min(nxtDp[d], dp[prevD] + cost);
                }
            }
        }
        dp = nxtDp;
    }

    return Math.min(...dp);
};
